export function CacheInvalidation({
  entryKey = "{{entryKey}}",
  trigger = "{{trigger}}",
  accent = "{{accent}}",
  showTimestamp = {{showTimestamp}},
}) {
  const reasons = {
    write: "a write to this key happened",
    "ttl-expiry": "TTL expired",
    manual: "manual purge requested",
  };
  return (
    <div style={{ font: "13px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10, padding: 12, borderRadius: 8, background: "#ffffff", border: "1px solid #24143018", marginBottom: 10 }}>
        <span style={{ flex: 1, fontFamily: "ui-monospace, monospace", fontSize: 11, textDecoration: "line-through", color: "#24143080" }}>{entryKey}</span>
        <span style={{ fontSize: 10, fontWeight: 700, padding: "3px 9px", borderRadius: 999, color: "#241430", background: accent }}>invalidated</span>
      </div>
      <p style={{ margin: 0, fontSize: 11, color: "#24143099" }}>Reason: {reasons[trigger]}{showTimestamp && " at 14:02:11"}</p>
    </div>
  );
}
